// RustboroCity_House1 (zone 585): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0106_room_RustboroCity_House1.txt
// Story (chapter Ch1, Sapphire data/maps/RustboroCity_House1/scripts.inc), after "// ---- story": the trader (Sapphire
// in-game trade 0: his Makuhita "Makit" for a Slakoth). Black 2's own in-game trade: entry 24 of a/1/6/3, rewritten
// with Sapphire's data by b2tools/patches/trades.py; names on lines 48/49 of system text 37 (src/text/overrides.json).
// People: data/story/ch1.json (the trader, uid 1 = Sapphire local id). Room tiles = Sapphire tiles + (1, 1).
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_story.inc"

    ScriptEntry Script_1
    ScriptEntry Script_2
    ScriptEntry Script_3    // the trader (RustboroCity_House1_EventScript_Trader), chapter Ch1
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    ParentActorMsg MSGFILE_SCRIPT, 0, 0, 0
    LastKeyWait
    ActorMsgClose
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt

Script_2:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 1, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt


// ---- story (chapter Ch1)
#define RH1_TRADE 24                                // Black 2 in-game trade 24 (b2tools/patches/trades.py)
#define RH1_SLOT 0x8020                             // party slot picked (as Black 2's own trade scripts, b2:1040.s)
#define RH1_OK 0x8021                               // 1 = a Pokémon was picked
#define RH1_CHECK 0x8022                            // FieldTradeCheck: 0 = the wanted species
#ifdef HOENN_EMERALD                                // (em_trades) Emerald: pokeemerald INGAME_TRADE_SEEDOT, the
#define RH1_WANTED SPECIES_RALTS                     // Camper's Seedot "Dots" for a Ralts (same trade 24, Emerald's
#else                                               // data; text src/text/script/emerald/0106_*)
#define RH1_WANTED SPECIES_SLAKOTH
#endif

Script_3:                                        // RustboroCity_House1_EventScript_Trader (lock, faceplayer)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RUSTBORO_NPC_TRADE_COMPLETED, L_RH1_Completed
    h_bufferspeciesname 1, RH1_WANTED               // GetInGameTradeSpeciesInfo: STR_VAR_1 the wanted species, STR_VAR_2
    FieldTradeGetSpecies HLIB_TMP, RH1_TRADE        //   the offered one (read from the trade, as b2:1272.s does)
    h_bufferspeciesname 2, HLIB_TMP
    h_yesno 2, HLIB_TMP                             // Do you nickname your Pokémon? ... trade your Slakoth for my Makuhita?
    h_goto_if_no HLIB_TMP, L_RH1_Decline
    MsgWinCloseAll
    WorkSetConst RH1_SLOT, 0
    WorkSetConst RH1_OK, 0
    CallPokeSelect 0, RH1_OK, RH1_SLOT, 0           // SelectMonForNPCTrade
    h_goto_if_ne RH1_OK, 1, L_RH1_Decline           // (none picked: Sapphire 0x8004 = 255)
    WorkSetConst RH1_CHECK, 0
    FieldTradeCheck RH1_CHECK, RH1_TRADE, RH1_SLOT  // GetTradeSpecies + compare with the wanted species
    h_goto_if_ne RH1_CHECK, 0, L_RH1_NotRequested
    FieldTradeStart RH1_TRADE, RH1_SLOT             // CreateInGameTradePokemon + DoInGameTradeScene
    h_msgbox 3                                      // Eheheheh, ooh, this is so exciting!
    h_setflag FLAG_RUSTBORO_NPC_TRADE_COMPLETED
    VMJump L_RH1_Release
L_RH1_Decline:
    h_msgbox 5                                      // Aww, it's a good Pokémon...
    VMJump L_RH1_Release
L_RH1_NotRequested:
    h_bufferspeciesname 1, RH1_WANTED               // bufferspeciesname 0, VAR_0x8009
    h_msgbox 4                                      // But that's no Slakoth. Tch, that's so disappointing...
    VMJump L_RH1_Release
L_RH1_Completed:
    h_msgbox 6                                      // Don't you get curious about what other people named their Pokémon?
L_RH1_Release:
    WorkSetConst RH1_CHECK, 0
    WorkSetConst RH1_OK, 0
    WorkSetConst RH1_SLOT, 0
    h_release
    .balign 4, 0
